/**
 * Tower fire: whether an enemy is within firing range, and when Rapid Fire can apply.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    towerFireInRange, towerFireRapidFireEligible
 * depends    src/mechanics/combat/distances, src/mechanics/combat/types
 * used by    src/calculators/specs.generated, src/mechanics/combat/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { isEnemyInNormalFireRange } from './distances'
import type { TowerFireRangeCheck, TowerFireRapidFireGate } from './types'

export function towerFireInRange(input: TowerFireRangeCheck): boolean {
  return isEnemyInNormalFireRange(input.distanceFromTower, input.towerRangeDistance)
}

export function towerFireRapidFireEligible(gate: TowerFireRapidFireGate): boolean {
  return gate.labRapidFireMult >= 1 && gate.rapidFireFlagA && gate.rapidFireFlagB
}
